CASE WHEN "EqUUI_mZyt" IS NULL THEN 'unset' WHEN LOWER(TRIM("EqUUI_mZyt")) LIKE '%propert%manag%' OR LOWER(TRIM("EqUUI_mZyt")) LIKE '%landlord%' OR LOWER(TRIM("EqUUI_mZyt")) LIKE '%portfolio admin%' OR LOWER(TRIM("EqUUI_mZyt")) IN ('landlorf','lanloard','manager','peoperty manager','pm','poperty managerr','properry manager','property managerw','property manger') THEN 'property_manager' WHEN LOWER(TRIM("EqUUI_mZyt")) LIKE '%applic%' OR LOWER(TRIM("EqUUI_mZyt")) LIKE '%guarantor%' OR LOWER(TRIM("EqUUI_mZyt")) LIKE '%aplicant%' OR LOWER(TRIM("EqUUI_mZyt")) IN ('aplicant','app','appalicant','appcant','appicant','appki','appl','applcant','applciamn','applciant','applcuant','appli','applicaant','applicanty','applicnat','applicnatn','applifant','appliicant','applit','appliucant','applivcant','applklicant','appllicant','apploicant','appplicant','cant','eapplicant','oapplicant','pplicant','spplicant') THEN 'applicant' ELSE 'other' END
